*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101b2c;color:#fff;font-family:'DM Sans',sans-serif;touch-action:none}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;overflow:hidden;background:#98d9e8;isolation:isolate}#world{display:block;width:100%;height:100%;outline:0}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,17,31,.42),transparent 25%,transparent 67%,rgba(8,17,31,.48));z-index:1}.topbar{position:absolute;top:max(20px,env(safe-area-inset-top));left:30px;right:30px;display:flex;align-items:center;justify-content:space-between;z-index:3;pointer-events:none}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:39px;height:39px;display:grid;place-items:center;background:#b8f34a;color:#142332;font:900 25px 'Barlow Condensed';transform:skew(-8deg);box-shadow:4px 4px 0 #182735}.brand b{font:900 19px 'Barlow Condensed';letter-spacing:.08em}.brand b span{color:#c1fa58}.brand small{display:block;font-size:8px;letter-spacing:.2em;color:#d7e4ea;font-weight:700;margin-top:1px}.match-pill,.icon-btn{pointer-events:auto;background:rgba(16,30,43,.62);border:1px solid rgba(255,255,255,.2);backdrop-filter:blur(12px)}.match-pill{border-radius:20px;padding:9px 14px;display:flex;align-items:center;gap:8px;font-size:9px;font-weight:800;letter-spacing:.1em}.match-pill i,.map-dot{width:7px;height:7px;border-radius:50%;background:#c3f748;box-shadow:0 0 12px #c3f748}.match-pill span{color:#d5f87e;margin-left:5px;font-variant-numeric:tabular-nums}.icon-btn{width:34px;height:34px;border-radius:50%;font-size:17px}.glass{background:rgba(17,30,44,.78);border:1px solid rgba(255,255,255,.15);backdrop-filter:blur(12px);box-shadow:0 8px 25px rgba(8,16,24,.15)}.mission-card{position:absolute;top:88px;left:30px;z-index:2;display:flex;align-items:center;gap:11px;padding:11px 16px 11px 12px;border-radius:8px;min-width:195px}.mission-icon{width:32px;height:32px;background:#c3f748;color:#182636;display:grid;place-items:center;font-size:20px;border-radius:5px}.mission-card small,.weapon-card small{display:block;color:#aab8c5;font-size:8px;font-weight:800;letter-spacing:.14em}.mission-card b{display:block;font-size:11px;margin:2px 0 1px}.mission-card span{font-size:9px;color:#c1fa58}.map-card{position:absolute;right:30px;top:82px;width:170px;padding:10px;border-radius:9px;z-index:2}.map-head{display:flex;justify-content:space-between;align-items:center;font:700 10px 'Barlow Condensed';letter-spacing:.13em;padding:0 2px 7px}.map-dot{width:6px;height:6px}#minimap{width:100%;height:auto;display:block;border-radius:4px;background:#89c995}.storm-line{font-size:7px;letter-spacing:.1em;color:#bac7d0;margin-top:7px;display:flex;align-items:center;gap:5px}.storm-line i{width:5px;height:5px;border-radius:50%;background:#bdff4a}.storm-line b{margin-left:auto;color:#fff;font-variant-numeric:tabular-nums}.center-reticle{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:24px;height:24px;z-index:2;pointer-events:none}.center-reticle i{position:absolute;width:5px;height:2px;background:#fff;box-shadow:0 1px 3px #142434}.center-reticle i:nth-child(1){left:0;top:11px}.center-reticle i:nth-child(2){right:0;top:11px}.center-reticle i:nth-child(3){top:0;left:11px;width:2px;height:5px}.center-reticle i:nth-child(4){bottom:0;left:11px;width:2px;height:5px}.center-reticle b{position:absolute;width:2px;height:2px;border-radius:50%;background:#fff;top:11px;left:11px}.hitmarker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.6);font:20px sans-serif;color:#d8ff64;opacity:0;z-index:3;pointer-events:none}.hitmarker.show{animation:hit .18s ease-out}@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) scale(.6)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.3)}}.toast{position:absolute;top:23%;left:50%;transform:translateX(-50%);z-index:4;font:800 12px 'Barlow Condensed';letter-spacing:.12em;text-shadow:0 2px 8px #122;opacity:0;transition:opacity .2s}.toast.show{opacity:1}.kill-feed{position:absolute;top:174px;right:30px;z-index:2;display:flex;flex-direction:column;align-items:flex-end;gap:5px;font-size:9px;text-shadow:0 1px 4px #111}.kill-feed div{background:rgba(16,30,43,.65);border-radius:3px;padding:5px 8px}.bottom-hud{position:absolute;bottom:max(28px,env(safe-area-inset-bottom));left:30px;right:30px;display:flex;align-items:flex-end;gap:12px;z-index:3;pointer-events:none}.player-stats{width:185px;display:grid;grid-template-columns:1fr 30px;gap:5px 8px;margin-bottom:3px}.stat-label{display:flex;align-items:center;gap:5px;font-size:8px;letter-spacing:.1em;color:#e5edf0}.stat-label span{color:#ff6968;font-size:12px}.stat-label strong{margin-left:auto;font:700 10px 'DM Sans';font-variant-numeric:tabular-nums}.shield-label span{color:#66d7ff}.bar{height:5px;background:rgba(15,26,38,.68);border-radius:4px;overflow:hidden;grid-column:span 2}.bar i{display:block;height:100%;width:100%;background:#ff6769;border-radius:4px;transition:width .2s}.bar.shield i{background:#65d9ff}.weapon-card{height:56px;display:flex;align-items:center;gap:9px;padding:0 12px;border-radius:7px;min-width:215px;position:relative;overflow:hidden}.weapon-art{font-size:27px;color:#d7f771;transform:rotate(-30deg)}.weapon-card>div:nth-child(2){min-width:73px}.weapon-card>div:nth-child(2) b{font:700 13px 'Barlow Condensed';letter-spacing:.02em}.ammo{margin-left:auto;display:flex;align-items:baseline;gap:3px}.ammo strong{font:800 23px 'Barlow Condensed';font-variant-numeric:tabular-nums}.ammo span{font-size:10px;color:#aebdc8}.ammo i{font-style:normal}.reload-progress{position:absolute;bottom:0;left:0;height:2px;width:0;background:#c3f748;transition:width .1s}.quick-slots{display:flex;gap:5px;pointer-events:auto}.slot{position:relative;width:45px;height:48px;border:1px solid rgba(255,255,255,.3);background:rgba(18,30,44,.6);border-radius:6px;display:grid;place-items:center;font-size:20px;color:#d8e6e9}.slot.active{border:2px solid #c5f54c;background:rgba(54,73,34,.72)}.slot small{position:absolute;top:3px;left:5px;font-size:8px;color:#c4cbd0}.slot i{position:absolute;bottom:3px;right:4px;font-size:8px;font-style:normal;background:#172536;padding:1px 3px;border-radius:2px}.controls{position:absolute;bottom:99px;left:30px;z-index:2;color:#deeaed;font-size:8px;letter-spacing:.1em;opacity:.72}.controls span{font-weight:800;border:1px solid rgba(255,255,255,.65);padding:3px 5px;border-radius:3px;margin:0 4px}.screen-cover{position:absolute;inset:0;z-index:8;display:flex;align-items:center;justify-content:flex-start;padding:clamp(28px,8vw,130px);background:linear-gradient(90deg,rgba(9,19,32,.78),rgba(9,19,32,.25) 55%,rgba(9,19,32,.05)),linear-gradient(0deg,rgba(6,18,30,.4),transparent 70%);transition:opacity .45s,visibility .45s}.screen-cover.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-backdrop{position:absolute;inset:0;z-index:-1;background:radial-gradient(ellipse at 68% 32%,rgba(201,241,99,.13),transparent 35%),linear-gradient(115deg,rgba(12,27,42,.35),transparent 80%)}.start-content{max-width:500px;margin-top:10px}.eyebrow{font-size:10px;font-weight:800;letter-spacing:.2em;color:#d3f878;display:flex;align-items:center;gap:9px}.eyebrow i{width:7px;height:7px;border-radius:50%;background:#d3f878;box-shadow:0 0 12px #c3f748}.start-content h1{font:900 clamp(76px,12vw,142px)/.72 'Barlow Condensed';letter-spacing:-.03em;margin:28px 0 25px;text-shadow:0 6px 25px rgba(0,0,0,.2)}.start-content h1 span{color:#cbf45e}.start-content p{font-size:15px;color:#e0e8e9;letter-spacing:.02em;margin:0 0 28px}.start-content p b{color:#fff}.start-facts{display:flex;gap:33px;margin-bottom:29px}.start-facts div{display:flex;flex-direction:column;gap:2px}.start-facts b{font:800 25px 'Barlow Condensed';color:#f3f7ef}.start-facts small{font-size:8px;letter-spacing:.12em;color:#c0cbd0;font-weight:700}.play-button{border:0;background:#c6f34f;color:#172635;padding:15px 20px;min-width:220px;display:flex;justify-content:space-between;align-items:center;font:900 12px 'DM Sans';letter-spacing:.08em;cursor:pointer;clip-path:polygon(0 0,94% 0,100% 30%,100% 100%,6% 100%,0 70%);box-shadow:0 8px 30px rgba(192,244,71,.18);transition:transform .15s,background .15s}.play-button:hover{background:#dcff74;transform:translateY(-2px)}.play-button span{font-size:18px}.start-note{margin-top:16px;font-size:8px;letter-spacing:.08em;color:#c3d0d7}.start-note b{color:white}.island-caption{position:absolute;bottom:27px;right:35px;font:700 10px 'Barlow Condensed';letter-spacing:.16em;color:#eaf1ea}.island-caption span{color:#c5f44e;font-size:15px}.island-caption i{font-style:normal;color:#c3f748;margin:0 7px}.end-screen{background:rgba(9,19,32,.68);justify-content:center;text-align:center;padding:24px;backdrop-filter:blur(6px)}.end-content{max-width:440px}.end-content .eyebrow{justify-content:center}.end-content h2{font:900 clamp(55px,10vw,90px)/.95 'Barlow Condensed';color:#d0f665;margin:16px 0 8px}.end-content p{color:#dce7e9}.result-stats{display:flex;justify-content:center;gap:50px;margin:25px 0}.result-stats div{display:flex;flex-direction:column;gap:4px}.result-stats b{font:800 30px 'Barlow Condensed'}.result-stats small{font-size:8px;letter-spacing:.12em;color:#bbcad0}.end-content .play-button{margin:auto}.mobile-controls{display:none}.rotate-hint{display:none}
