osition:absolute;bottom:0;left:38px;font-size:7px;letter-spacing:.14em;color:rgba(255,255,255,.7);font-weight:800}.look-zone{position:absolute;right:0;top:25%;bottom:21%;width:45%;pointer-events:auto;touch-action:none}.look-zone>span{left:auto;right:22px;bottom:7px}.touch-action{position:absolute;pointer-events:auto;touch-action:none;border:1px solid rgba(255,255,255,.45);border-radius:50%;background:rgba(17,30,42,.62);backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;flex-direction:column;box-shadow:0 4px 15px rgba(0,0,0,.2)}.touch-action span{font-size:22px;line-height:1}.touch-action small{font-size:7px;font-weight:800;letter-spacing:.08em;margin-top:2px}.fire-action{width:72px;height:72px;right:18px;bottom:105px;background:rgba(196,242,73,.85);color:#182735;border:2px solid rgba(255,255,255,.8)}.fire-action span{font-size:25px}.build-action{width:47px;height:47px;right:105px;bottom:119px}.build-action span{font-size:18px}.reload-action{width:40px;height:40px;right:31px;bottom:188px;font-size:21px}.reload-action span{font-size:20px}.screen-cover{padding:30px 25px;align-items:center;background:linear-gradient(90deg,rgba(9,19,32,.78),rgba(9,19,32,.30) 100%),linear-gradient(0deg,rgba(6,18,30,.3),transparent 70%)}.start-content{margin:0}.eyebrow{font-size:8px}.start-content h1{font-size:88px;margin:23px 0 19px}.start-content p{font-size:12px;margin-bottom:20px}.start-facts{gap:22px;margin-bottom:23px}.start-facts b{font-size:20px}.start-facts small{font-size:7px}.play-button{min-width:205px;padding:13px 17px;font-size:10px}.start-note{font-size:7px;max-width:270px;line-height:1.6}.island-caption{bottom:15px;right:15px;font-size:8px}.center-reticle{width:18px;height:18px}.center-reticle i:nth-child(1){top:8px}.center-reticle i:nth-child(2){top:8px}.center-reticle i:nth-child(3){left:8px}.center-reticle i:nth-child(4){left:8px}.center-reticle b{left:8px;top:8px}.toast{top:34%}}
@media(max-height:520px) and (orientation:landscape){.start-content h1{font-size:68px;margin:14px 0}.start-content p{margin-bottom:12px}.start-facts{margin-bottom:13px}.mission-card{top:54px}.map-card{top:54px}.bottom-hud{bottom:8px}.move-zone{bottom:67px}.fire-action{bottom:68px}.build-action{bottom:82px}.reload-action{bottom:148px}.island-caption{bottom:10px}}
