import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const $ = (s) => document.querySelector(s);
const canvas = $('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x91d4e4);
scene.fog = new THREE.Fog(0x91d4e4, 65, 155);
const camera = new THREE.PerspectiveCamera(56, 1, .1, 240);
const renderer = new THREE.WebGLRenderer({canvas, antialias: true, powerPreference: 'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.65));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
scene.add(new THREE.HemisphereLight(0xdff7ff, 0x51683e, 2.15));
const sun = new THREE.DirectionalLight(0xfff0cc, 3.2);
sun.position.set(-35, 65, 28); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -80; sun.shadow.camera.right = 80; sun.shadow.camera.top = 80; sun.shadow.camera.bottom = -80;
scene.add(sun);

const mat = (color, roughness=.8) => new THREE.MeshStandardMaterial({color, roughness});
const grassMat = mat(0x74a84f), darkGrass = mat(0x5c9149), trunkMat = mat(0x795137), stoneMat = mat(0x87938b);
const mapGroup = new THREE.Group(); scene.add(mapGroup);
// Procedural rolling island with a rocky coastline.
const terrainGeo = new THREE.PlaneGeometry(166, 166, 100, 100);
const pos = terrainGeo.attributes.position, colors = [];
for (let i=0;i<pos.count;i++) {
  const x=pos.getX(i), z=-pos.getY(i), r=Math.hypot(x,z);
  let h = .72*Math.sin(x*.11)*Math.cos(z*.10)+.42*Math.sin((x+z)*.19)+.2*Math.cos(z*.31);
  const edge = THREE.MathUtils.clamp((r-56)/26,0,1);
  h = h*(1-edge) + (-5 - edge*4);
  pos.setZ(i,h);
  const c = new THREE.Color(r>66?0x477f83:(h>1.3?0x9ca17c:(h<-.8?0x638d4c:0x79aa50)));
  c.multiplyScalar(.94 + Math.random()*.12); colors.push(c.r,c.g,c.b);
}
terrainGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
terrainGeo.computeVertexNormals(); terrainGeo.rotateX(-Math.PI/2);
const terrain = new THREE.Mesh(terrainGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1})); terrain.receiveShadow=true; mapGroup.add(terrain);
const water = new THREE.Mesh(new THREE.CircleGeometry(115,72),new THREE.MeshStandardMaterial({color:0x4ab4c7,roughness:.36,metalness:.08})); water.rotation.x=-Math.PI/2; water.position.y=-6.1; mapGroup.add(water);
// Patchy clearings, beach stones, and conifer silhouettes.
const rng = (a,b)=>a+Math.random()*(b-a);
function tree(x,z,scale=1){
  const g=new THREE.Group(); g.position.set(x,groundY(x,z),z); g.scale.setScalar(scale);
  const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.21,1.9,6),trunkMat); trunk.position.y=.9; trunk.castShadow=true;g.add(trunk);
  for(let i=0;i<3;i++){const cone=new THREE.Mesh(new THREE.ConeGeometry(1.05-i*.2,1.65,7),mat(i===0?0x347b5f:0x428c61));cone.position.y=1.55+i*.72;cone.castShadow=true;g.add(cone)}
  mapGroup.add(g);
}
function groundY(x,z){return .72*Math.sin(x*.11)*Math.cos(z*.10)+.42*Math.sin((x+z)*.19)+.2*Math.cos(z*.31)}
for(let i=0;i<115;i++){
  const a=rng(0,Math.PI*2),r=Math.sqrt(rng(12,3100)),x=Math.cos(a)*r,z=Math.sin(a)*r;
  if(Math.hypot(x,z)>54 || (Math.abs(x)<12&&Math.abs(z)<10)) continue;
  tree(x,z,rng(.68,1.16));
}
function cabin(x,z,color=0xe7cf9f){
  const g=new THREE.Group();g.position.set(x,groundY(x,z),z);
  const base=new THREE.Mesh(new THREE.BoxGeometry(6,3.2,5),mat(color));base.position.y=1.6;base.castShadow=true;base.receiveShadow=true;g.add(base);
  const roof=new THREE.Mesh(new THREE.ConeGeometry(4.5,2.4,4),mat(0x42545b));roof.rotation.y=Math.PI/4;roof.position.y=4.2;roof.castShadow=true;g.add(roof);
  const door=new THREE.Mesh(new THREE.BoxGeometry(.85,1.7,.1),mat(0x604633));door.position.set(0,.85,2.56);g.add(door);
  const winMat=new THREE.MeshStandardMaterial({color:0x8de4e4,emissive:0x246e70,emissiveIntensity:.3});
  for(const wx of [-1.8,1.8]){const w=new THREE.Mesh(new THREE.BoxGeometry(.8,.8,.11),winMat);w.position.set(wx,1.9,2.56);g.add(w)}
  mapGroup.add(g);
}
cabin(-25,-20,0xd7c394); cabin(23,-25,0xe5d6ac); cabin(29,17,0xd8c8a4); cabin(-28,22,0xe5d2a0);
// A few vivid rocks and glowing loot caches.
for(let i=0;i<30;i++){const a=rng(0,Math.PI*2),r=rng(13,52),x=Math.cos(a)*r,z=Math.sin(a)*r;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(rng(.4,1.1),0),stoneMat);rock.position.set(x,groundY(x,z)+.35,z);rock.scale.y=.7;rock.rotation.set(rng(0,2),rng(0,3),rng(0,2));rock.castShadow=true;mapGroup.add(rock)}

const player = {pos:new THREE.Vector3(0,0,8),yaw:0,health:100,shield:50,ammo:24,reserve:96,kills:0,alive:true,speed:9.5,builds:30};
function makeCharacter(color, accent, isPlayer=false){
 const g=new THREE.Group();
 const body=new THREE.Mesh(new THREE.CapsuleGeometry(.48,.95,4,8),mat(color));body.position.y=1.35;body.castShadow=true;g.add(body);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.35,12,10),mat(0xf0c6a2));head.position.y=2.2;head.castShadow=true;g.add(head);
 const hair=new THREE.Mesh(new THREE.SphereGeometry(.36,10,7,0,Math.PI*2,0,Math.PI*.56),mat(accent));hair.position.y=2.31;g.add(hair);
 const pack=new THREE.Mesh(new THREE.BoxGeometry(.72,.76,.32),mat(accent));pack.position.set(0,1.38,.48);g.add(pack);
 const gun=new THREE.Mesh(new THREE.BoxGeometry(.18,.18,.9),mat(0x27323a,.35));gun.position.set(.45,1.45,-.48);g.add(gun);
 const barrel=new THREE.Mesh(new THREE.CylinderGeometry(.045,.045,.36,7),mat(0xc3ee69,.3));barrel.rotation.x=Math.PI/2;barrel.position.set(.45,1.46,-.98);g.add(barrel);
 if(isPlayer){const scarf=new THREE.Mesh(new THREE.TorusGeometry(.37,.1,6,12),mat(0xc7f251));scarf.position.y=1.88;scarf.rotation.x=Math.PI/2;g.add(scarf)}
 return g;
}
const playerMesh=makeCharacter(0x386f90,0x21394d,true);scene.add(playerMesh);
const botColors=[0xcf6351,0x8c65c2,0xe2a843,0x4e9e84,0x5290bd,0xb64d79,0x9b8654];
const bots=[];
for(let i=0;i<7;i++){
 let a=(i/7)*Math.PI*2+.4,r=22+Math.random()*25,x=Math.cos(a)*r,z=Math.sin(a)*r;
 const mesh=makeCharacter(botColors[i],0x293848);mesh.position.set(x,groundY(x,z),z);scene.add(mesh);
 bots.push({mesh,pos:new THREE.Vector3(x,0,z),health:100,alive:true,think:Math.random()*2,fire:1+Math.random()*2,walk:Math.random()*8,hitFlash:0,name:['Sombra','Rayo','Kiwi','Nómada','Pixel','Lince','Bruma'][i]});
}
// Floating supply crates and restorative pickups.
const pickups=[];
