function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.fov=w<700?62:56;camera.updateProjectionMatrix()}
addEventListener('resize',resize);resize();
const mini=$('#minimap'),mctx=mini.getContext('2d');
function updateMinimap(){const w=mini.width,c=w/2,s=w/140;mctx.clearRect(0,0,w,w);mctx.fillStyle='#78bd82';mctx.fillRect(0,0,w,w);mctx.fillStyle='rgba(48,117,129,.45)';for(let i=0;i<8;i++){const x=(i*41+12)%w,y=(i*67+23)%w;mctx.beginPath();mctx.arc(x,y,7+i%3*3,0,Math.PI*2);mctx.fill()}mctx.strokeStyle='rgba(169,239,255,.92)';mctx.lineWidth=2;mctx.beginPath();mctx.arc(c,c,stormRadius*s,0,Math.PI*2);mctx.stroke();mctx.fillStyle='rgba(100,205,255,.12)';mctx.fillRect(0,0,w,w);mctx.save();mctx.translate(c,c);mctx.rotate(-yaw);mctx.fillStyle='#e8ff7c';mctx.beginPath();mctx.moveTo(0,-5);mctx.lineTo(-4,4);mctx.lineTo(4,4);mctx.fill();mctx.restore();for(const b of bots)if(b.alive){mctx.fillStyle='#ef6971';mctx.beginPath();mctx.arc(c+b.pos.x*s,c+b.pos.z*s,2.4,0,Math.PI*2);mctx.fill()}}
function fmt(t){t=Math.max(0,Math.floor(t));return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')}
function setToast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(setToast.timer);setToast.timer=setTimeout(()=>el.classList.remove('show'),1350)}
function updateHUD(){const hp=Math.max(0,player.health),sh=Math.max(0,player.shield);$('#health-num').textContent=Math.ceil(hp);$('#shield-num').textContent=Math.ceil(sh);$('#health-bar').style.width=hp+'%';$('#shield-bar').style.width=(sh/50*100)+'%';$('#ammo-now').textContent=player.ammo;$('#ammo-reserve').textContent=player.reserve;$('#build-count').textContent=player.builds;$('#alive-label').textContent=(bots.filter(b=>b.alive).length+1)+' jugadores restantes';$('#match-clock').textContent=fmt(elapsed);$('#storm-time').textContent=fmt(Math.max(0,stormTimer-elapsed))}
function isMobile(){return matchMedia('(pointer:coarse)').matches||innerWidth<700}
function startGame(){if(started&&!ended)return;started=true;ended=false;$('#start-screen').classList.add('hidden');$('#end-screen').classList.add('hidden');if(!isMobile())canvas.requestPointerLock?.();setToast('¡A POR ELLOS!')}
$('#play-btn').addEventListener('click',startGame);$('#again-btn').addEventListener('click',()=>location.reload());
$('#sound-btn').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'×':'♫';setToast(muted?'SONIDO DESACTIVADO':'SONIDO ACTIVADO')});
function finish(win){if(ended)return;ended=true;player.alive=false;fireHeld=false;$('#end-title').textContent=win?'¡VICTORIA!':'ELIMINADO';$('#end-title').style.color=win?'#d0f665':'#ff7775';$('#end-copy').textContent=win?'La isla es tuya. ¡Increíble partida!':'Los rivales se quedan con la isla. ¡A por la siguiente!';$('#result-kills').textContent=player.kills;$('#result-time').textContent=fmt(elapsed);$('#end-screen').classList.remove('hidden')}
function damagePlayer(amount){if(!player.alive)return;let d=amount;if(player.shield>0){const use=Math.min(player.shield,d);player.shield-=use;d-=use}player.health=Math.max(0,player.health-d);updateHUD();if(player.health<=0)finish(false)}
function addFeed(text){const feed=$('#kill-feed'),d=document.createElement('div');d.innerHTML=text;feed.prepend(d);while(feed.children.length>3)feed.lastChild.remove();setTimeout(()=>d.remove(),4800)}
const keys=new Set();addEventListener('keydown',e=>{keys.add(e.code);if(e.code==='Escape')document.exitPointerLock?.();if(e.code==='KeyR')reload();if(e.code==='KeyF')buildWall();if(e.code==='Space'){fireHeld=true;e.preventDefault()}if(e.code==='ShiftLeft'||e.code==='ShiftRight')e.preventDefault()});addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='Space')fireHeld=false});
$('#world').addEventListener('click',()=>{if(!started)startGame();else if(!isMobile()&&document.pointerLockElement!==canvas)canvas.requestPointerLock?.()});
addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas){yaw-=e.movementX*.0024;pitch=THREE.MathUtils.clamp(pitch-e.movementY*.0015,-.35,.55)}});
canvas.addEventListener('mousedown',e=>{if(e.button===0&&started)fireHeld=true});addEventListener('mouseup',e=>{if(e.button===0)fireHeld=false});
function reload(){if(reloading||player.ammo===24||player.reserve<=0||!started||ended)return;reloading=true;reloadTime=1.35;setToast('RECARGANDO')}
function buildWall(){if(!started||ended||player.builds<=0||buildCooldown>0)return;player.builds--;buildCooldown=1.4;const f=new THREE.Vector3(Math.sin(yaw),0,-Math.cos(yaw)),p=player.pos.clone().addScaledVector(f,2.6),wall=new THREE.Mesh(new THREE.BoxGeometry(4.2,2.8,.34),mat(0xb9d68a));wall.position.set(p.x,groundY(p.x,p.z)+1.4,p.z);wall.rotation.y=yaw;wall.castShadow=true;wall.receiveShadow=true;scene.add(wall);setTimeout(()=>{scene.remove(wall);wall.geometry.dispose();wall.material.dispose()},12000);updateHUD();setToast('¡MURO CONSTRUIDO!')}
$('#reload-btn').addEventListener('pointerdown',e=>{e.preventDefault();reload()});$('#build-btn').addEventListener('pointerdown',e=>{e.preventDefault();buildWall()});
const fireBtn=$('#fire-btn');fireBtn.addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true;fireBtn.setPointerCapture(e.pointerId)});fireBtn.addEventListener('pointerup',()=>fireHeld=false);fireBtn.addEventListener('pointercancel',()=>fireHeld=false);fireBtn.addEventListener('lostpointercapture',()=>fireHeld=false);
const moveZone=$('.move-zone'),knob=$('.stick-knob');moveZone.addEventListener('pointerdown',e=>{e.preventDefault();joystick.active=true;joystick.id=e.pointerId;const r=moveZone.getBoundingClientRect();joystick.cx=r.left+r.width/2;joystick.cy=r.top+r.height/2;moveZone.setPointerCapture(e.pointerId);moveStick(e)});moveZone.addEventListener('pointermove',e=>{if(joystick.active&&e.pointerId===joystick.id)moveStick(e)});
function moveStick(e){let dx=e.clientX-joystick.cx,dy=e.clientY-joystick.cy,len=Math.hypot(dx,dy),max=39;if(len>max){dx=dx/len*max;dy=dy/len*max}knob.style.transform=`translate(${dx}px,${dy}px)`;moveInput.x=dx/max;moveInput.y=dy/max}
function stopStick(e){if(e.pointerId!==joystick.id)return;joystick.active=false;moveInput={x:0,y:0};knob.style.transform='translate(0,0)'}moveZone.addEventListener('pointerup',stopStick);moveZone.addEventListener('pointercancel',stopStick);
const lookZone=$('.look-zone');lookZone.addEventListener('pointerdown',e=>{lookTouch.active=true;lookTouch.id=e.pointerId;lookTouch.x=e.clientX;lookZone.setPointerCapture(e.pointerId)});lookZone.addEventListener('pointermove',e=>{if(!lookTouch.active||e.pointerId!==lookTouch.id)return;const dx=e.clientX-lookTouch.x;lookTouch.x=e.clientX;yaw-=dx*.008});function stopLook(e){if(e.pointerId===lookTouch.id)lookTouch.active=false}lookZone.addEventListener('pointerup',stopLook);lookZone.addEventListener('pointercancel',stopLook);
function eliminate(b){if(!b.alive)return;b.alive=false;scene.remove(b.mesh);player.kills++;addFeed(`<b style="color:#c8f45e">TÚ</b>　✦　${b.name}`);pickup(b.pos.x+1,b.pos.z,'ammo');setToast('¡RIVAL ELIMINADO!');updateHUD();if(bots.every(x=>!x.alive))finish(true)}
function shot(){if(!started||ended||reloading||fireCooldown>0)return;if(player.ammo<=0){reload();return}player.ammo--;fireCooldown=.17;updateHUD();const direction=new THREE.Vector3();camera.getWorldDirection(direction);let chosen=null,best=Infinity;for(const b of bots){if(!b.alive)continue;const target=b.pos.clone().add(new THREE.Vector3(0,1.35,0)),rel=target.clone().sub(camera.position),along=rel.dot(direction);if(along<0||along>58)continue;const miss=rel.addScaledVector(direction,-along).length();if(miss<Math.max(.75,along*.025)&&along<best){best=along;chosen=b}}const origin=playerMesh.position.clone().add(new THREE.Vector3(0,1.55,0)).add(new THREE.Vector3(Math.sin(yaw)*.5,0,-Math.cos(yaw)*.5)),end=chosen?chosen.pos.clone().add(new THREE.Vector3(0,1.35,0)):camera.position.clone().addScaledVector(direction,55),geo=new THREE.BufferGeometry().setFromPoints([origin,end]),line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xd9ff75,transparent:true,opacity:.9}));scene.add(line);setTimeout(()=>{scene.remove(line);geo.dispose();line.material.dispose()},75);if(chosen){chosen.health-=34;$('#hitmarker').classList.remove('show');void $('#hitmarker').offsetWidth;$('#hitmarker').classList.add('show');if(chosen.health<=0)eliminate(chosen)}}

